import{_ as t,c as e,o as s,b0 as i}from"./chunks/framework.C5ev1SXp.js";const d="/scm-docs/assets/rx-path.mtuVnXnf.svg",k=JSON.parse('{"title":"LV020-网络通信实验","description":null,"frontmatter":{"title":"LV020-网络通信实验","date":"2026-10-14T21:35:41.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/ethernet/126d628e13a5205f2a80bf1e","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-14T21:35:41.517Z","fulluuid":"f2a80bf1e06d4198a6e5792ba8343a6d","useduuid":"f2a80bf1e"}},"headers":[],"relativePath":"sdoc/advanced-chapter/ethernet/126d628e13a5205f2a80bf1e.md","filePath":"sdoc/30-进阶篇/06-以太网/LV020-网络通信实验.md","lastUpdated":1792231946000}'),n={name:"sdoc/advanced-chapter/ethernet/126d628e13a5205f2a80bf1e.md"};function l(o,a,r,p,h,c){return s(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="lv020-网络通信实验" tabindex="-1">LV020-网络通信实验 <a class="header-anchor" href="#lv020-网络通信实验" aria-label="Permalink to &quot;LV020-网络通信实验&quot;">​</a></h1><h2 id="一、-实验准备" tabindex="-1">一、 实验准备 <a class="header-anchor" href="#一、-实验准备" aria-label="Permalink to &quot;一、 实验准备&quot;">​</a></h2><h3 id="_1-硬件连接" tabindex="-1">1. 硬件连接 <a class="header-anchor" href="#_1-硬件连接" aria-label="Permalink to &quot;1. 硬件连接&quot;">​</a></h3><ul><li>一根网线：板子与 PC 直连（现代网卡能自动翻转，不需要交叉线），或者两端都接在同一台交换机/路由器上。</li><li>一根 USB 线：板载 CH340 提供串口终端，用来观察板子打印的日志、输入文本命令。</li></ul><h3 id="_2-网络参数" tabindex="-1">2. 网络参数 <a class="header-anchor" href="#_2-网络参数" aria-label="Permalink to &quot;2. 网络参数&quot;">​</a></h3><p>参数写死在 <code>atk-f103/Components/lwip-2.1.3/port/lwip_comm.h</code> 里，改 IP 要重新编译：</p><table tabindex="0"><thead><tr><th>项</th><th>板子（默认）</th><th>PC 侧要求</th></tr></thead><tbody><tr><td>IP 地址</td><td>192.168.16.30</td><td>设成同网段的另一个地址，如 192.168.16.100</td></tr><tr><td>子网掩码</td><td>255.255.255.0</td><td>一致</td></tr><tr><td>网关</td><td>192.168.16.1</td><td>直连时用不到，可留空</td></tr></tbody></table><blockquote><p>同网段通信<strong>不走网关</strong>，所以 PC 这块网卡配不配网关都不影响 ping 板子。但如果随便填了一个实际上不存在的网关，PC 上其它跨网段的访问会莫名其妙失败，排查时容易误判——直连实验建议留空。</p></blockquote><h3 id="_3-上电自检输出" tabindex="-1">3. 上电自检输出 <a class="header-anchor" href="#_3-上电自检输出" aria-label="Permalink to &quot;3. 上电自检输出&quot;">​</a></h3><p>DM9000 的初始化在 <code>lwip_comm_init()</code> 里，而它在 IAP 业务层被调用。上电后串口应当依次打出：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ATK-F103 USART1 ready, SystemCoreClock = 72000000 Hz, build &lt;日期&gt; &lt;时间&gt;</span></span>
<span class="line"><span>IAP: ready, waiting for app.img frame (magic IAPBIN01, max payload 131072 bytes, frame timeout 3000 ms)</span></span>
<span class="line"><span>USART1: commands: &#39;go&#39; jump to APP, &#39;reboot&#39; restart chip</span></span>
<span class="line"><span>DM9000: ID = 0x90000A46</span></span>
<span class="line"><span>lwIP: MAC 02-00-00-XX-XX-XX, IP 192.168.16.30</span></span>
<span class="line"><span>lwIP: RX mode = interrupt (EXTI6 falling edge)</span></span>
<span class="line"><span>lwIP: ready, ping 192.168.16.30 to test</span></span>
<span class="line"><span>IAP-TCP: listening on port 8888</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>逐行含义：</p><table tabindex="0"><thead><tr><th>输出</th><th>说明</th></tr></thead><tbody><tr><td><code>DM9000: ID = 0x90000A46</code></td><td>芯片认到了。<strong>不是这个值就停下</strong>，先查 FSMC 与片选</td></tr><tr><td><code>lwIP: MAC 02-00-00-XX-XX-XX</code></td><td>MAC 由芯片 UID 生成：高三字节固定本地管理地址块，低三字节取自 <code>0x1FFFF7E8</code></td></tr><tr><td><code>lwIP: RX mode = interrupt</code></td><td>当前收包走 EXTI 中断；显示 <code>polling</code> 说明宏被改成了轮询</td></tr><tr><td><code>lwIP: ready, ping ... to test</code></td><td><code>lwip_comm_init()</code> 返回成功，可以开始 ping</td></tr><tr><td><code>IAP-TCP: listening on port 8888</code></td><td>TCP 升级通道已监听</td></tr></tbody></table><p><strong>如果只看到 <code>lwIP: DM9000 init failed</code></strong>，说明 <code>DM9000_Init()</code> 返回了非 0，也就是 ID 读错。这时不用怀疑协议栈，直接回到硬件层查 FSMC 与片选。</p><h2 id="二、-实验一-ping-通" tabindex="-1">二、 实验一：ping 通 <a class="header-anchor" href="#二、-实验一-ping-通" aria-label="Permalink to &quot;二、 实验一：ping 通&quot;">​</a></h2><h3 id="_1-操作与预期" tabindex="-1">1. 操作与预期 <a class="header-anchor" href="#_1-操作与预期" aria-label="Permalink to &quot;1. 操作与预期&quot;">​</a></h3><p>这是最省事的验证手段：ping 只要用上 ARP、ICMP、IP 三层，能通就说明&quot;DM9000 收发 + 协议栈 + 网络参数&quot;整条链路都活着，而且不需要写任何上位机代码。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.16.30</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>预期：</p><ul><li>PC 侧先看到 ARP 请求、再收到 ICMP 应答，<code>ping</code> 正常返回；</li><li>板子串口没有额外的报错输出（板子不打爆日志本身就是好消息）。</li></ul><h3 id="_2-ping-不通时的排查顺序" tabindex="-1">2. ping 不通时的排查顺序 <a class="header-anchor" href="#_2-ping-不通时的排查顺序" aria-label="Permalink to &quot;2. ping 不通时的排查顺序&quot;">​</a></h3><p>按下表的顺序查（按&quot;从物理到协议&quot;排，逐层砍）：</p><table tabindex="0"><thead><tr><th>现象</th><th>先查什么</th></tr></thead><tbody><tr><td>网口指示灯不亮</td><td>网线、对端口，以及 PHY 是否上电（DM9000 内部 PHY 靠 <code>GPCR</code> / <code>GPR</code> 控制）</td></tr><tr><td>灯亮但 ping 无应答</td><td>串口有没有打出 <code>DM9000: ID = 0x90000A46</code>；MAC / IP 打印是否正常</td></tr><tr><td>PC 收到 ARP 却没有应答</td><td>掩码是否一致、PC 是否被配了网关</td></tr><tr><td>时通时不通</td><td>收包模式（中断/轮询）是否与预期一致，见第四节</td></tr></tbody></table><p>完整的排错决策树（含 <code>arp -a</code> 这一步）见 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb037fb528c36d5.html">LV050-一次ping的完整旅程</a> 第六节。</p><h2 id="三、-实验二-tcp-服务器" tabindex="-1">三、 实验二：TCP 服务器 <a class="header-anchor" href="#三、-实验二-tcp-服务器" aria-label="Permalink to &quot;三、 实验二：TCP 服务器&quot;">​</a></h2><p>板子上跑的是一个<strong>单连接 TCP 服务器</strong>，监听 8888 端口，用途是把固件帧从 PC 灌进 Bootloader。它的实现见 <code>port/iap_tcp.c</code>，与帧协议的关系见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a52a7c8f19d4b3.html">LV030-网络升级帧协议与三条通道</a>。</p><h3 id="_1-会话规则" tabindex="-1">1. 会话规则 <a class="header-anchor" href="#_1-会话规则" aria-label="Permalink to &quot;1. 会话规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>行为</th><th>实现</th></tr></thead><tbody><tr><td>并发连接</td><td>只允许一个，忙时直接 <code>tcp_abort</code> 拒绝</td></tr><tr><td>建连时</td><td>摘除串口字节流消费器（<code>usart1_set_rx_sink(0)</code>），由 TCP 独占喂帧状态机</td></tr><tr><td>断连时</td><td>恢复串口消费器，两边都能继续用</td></tr><tr><td>文本命令</td><td>TCP 字节在喂帧状态机前会先过一遍串口命令表，所以 <code>go</code> / <code>reboot</code> 走 TCP 同样有效</td></tr></tbody></table><h3 id="_2-先做一次不破坏数据的连通性测试" tabindex="-1">2. 先做一次不破坏数据的连通性测试 <a class="header-anchor" href="#_2-先做一次不破坏数据的连通性测试" aria-label="Permalink to &quot;2. 先做一次不破坏数据的连通性测试&quot;">​</a></h3><p>不需要跑升级脚本，用任意 TCP 客户端连一下就能验证&quot;DM9000 + lwIP + TCP&quot;三层都通：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.16.30</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8888</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>若 TCP 三次握手成功，板子会打印 <code>IAP-TCP: client connected, waiting for IAPBIN01 frame</code>；</li><li>断开后打印 <code>IAP-TCP: client disconnected, uart channel restored</code>。</li></ul><p>能看到这两行，就说明&quot;连不上&quot;这类问题已经排除，可以往下走真实升级。</p><h3 id="_3-真实升级-把-app-img-发进去" tabindex="-1">3. 真实升级：把 app.img 发进去 <a class="header-anchor" href="#_3-真实升级-把-app-img-发进去" aria-label="Permalink to &quot;3. 真实升级：把 app.img 发进去&quot;">​</a></h3><p>上位机脚本是 <code>tools/send_iap_tcp.py</code>，它依赖同目录的 <code>pack_iap.py</code>：给<strong>裸 bin</strong> 时会自动组帧，并先校验向量表。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 发送裸 bin（脚本自动打包成 IAPBIN01 帧）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/send_iap_tcp.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flash-app.bin</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 指定板子 IP 与端口</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/send_iap_tcp.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flash-app.bin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.16.30</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8888</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 只发 go 命令，让 Bootloader 跳转到 APP</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/send_iap_tcp.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.16.30</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>脚本会打印栈顶（MSP）、复位向量与载荷 CRC32，然后每次 <code>sendall()</code> 发 1460 字节（脚本里 <code>CHUNK = 1460</code> 的注释写&quot;对齐 TCP MSS&quot;），最后等回执。</p><p>【<strong>注意</strong>】1460 字节只是脚本<strong>每次写入 socket 的批量大小</strong>，不是线上 TCP 段的实际大小。线上分段由握手时协商出的 MSS 决定：本工程 <code>lwipopts.h</code> 未定义 <code>TCP_MSS</code>，走 lwIP 默认值 <strong>536</strong>，所以 PC 的 TCP 栈会把每个 1460 字节的大块再切成 ≤ 536 字节的小段发送——这就是为什么大文件传输时板子看到的包会比预期碎得多（MSS 与窗口的来历见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a51d3a6f2be804.html">LV015-lwIP配置与初始化</a> 第二节，传输层基础见 <a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb02d6a3f5e9c41.html">LV035-传输层端口UDP与TCP</a>）。</p><p>脚本最后的回执对照：</p><table tabindex="0"><thead><tr><th>回执</th><th>含义</th></tr></thead><tbody><tr><td><code>RECV OK</code></td><td>帧收齐且 CRC32 通过</td></tr><tr><td><code>FLASH OK</code></td><td>写入 Flash 并回读校验成功</td></tr><tr><td><code>FLASH ERR</code></td><td>写入失败</td></tr><tr><td><code>RECV ERR</code></td><td>收帧失败（超时/格式错），串口有具体原因</td></tr></tbody></table><p>板侧同一时刻也会打印对应日志。<strong>收到 <code>FLASH OK</code> 之后不会自动跳转</strong>，还要再发一次 <code>go</code>（或串口输入 <code>go</code>）——这是刻意留的确认环节，方便先回读确认写入结果。</p><h2 id="四、-实验三-收包模式的切换" tabindex="-1">四、 实验三：收包模式的切换 <a class="header-anchor" href="#四、-实验三-收包模式的切换" aria-label="Permalink to &quot;四、 实验三：收包模式的切换&quot;">​</a></h2><h3 id="_1-中断模式与轮询模式" tabindex="-1">1. 中断模式与轮询模式 <a class="header-anchor" href="#_1-中断模式与轮询模式" aria-label="Permalink to &quot;1. 中断模式与轮询模式&quot;">​</a></h3><p>DM9000 的收包有两种驱动方式，由 <code>dm9000.h</code> 里的宏选择：</p><table tabindex="0"><thead><tr><th>模式</th><th>宏值</th><th>工作机制</th><th>代价</th></tr></thead><tbody><tr><td>中断</td><td><code>DM9000_RX_INT_MODE = 1</code></td><td>PG6 下降沿 → EXTI6 → <code>HAL_GPIO_EXTI_Callback()</code> 置软件标志 → 主循环取包</td><td>中断与主循环都要碰总线，需要临界区</td></tr><tr><td>轮询</td><td><code>DM9000_RX_INT_MODE = 0</code></td><td>主循环每拍无条件查 RX FIFO</td><td>空转开销，但逻辑简单、不依赖中断</td></tr></tbody></table><img src="`+d+`" alt="收包路径：中断模式与轮询模式"><h3 id="_2-中断模式里那个必须清的标志" tabindex="-1">2. 中断模式里那个必须清的标志 <a class="header-anchor" href="#_2-中断模式里那个必须清的标志" aria-label="Permalink to &quot;2. 中断模式里那个必须清的标志&quot;">​</a></h3><p>DM9000 的 INT 引脚是<strong>电平保持型</strong>：有包时拉低，且只有把 <code>ISR</code> 里对应的位<strong>写 1 清除</strong>之后才会回到高电平。所以回调里不能只置标志就返回：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    isr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DM9000_ReadReg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(DM9000_ISR);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ((isr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ISR_PRS) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">U</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) { s_rx_flag </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    DM9000_WriteReg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(DM9000_ISR, isr);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* 关键: 写 1 清中断源 */</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HAL_GPIO_ReadPin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(DM9000_INT_GPIO_Port, DM9000_INT_Pin) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GPIO_PIN_RESET);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>漏掉这一步的典型症状是：<strong>第一次收包正常，之后所有包全丢</strong>——因为下降沿只出现过一次，之后 INT 一直保持在低电平。中断路径的完整说明见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5187d4be5a1c9.html">LV005-DM9000驱动实现</a> 第五节。</p><h3 id="_3-两种模式都保留的价值" tabindex="-1">3. 两种模式都保留的价值 <a class="header-anchor" href="#_3-两种模式都保留的价值" aria-label="Permalink to &quot;3. 两种模式都保留的价值&quot;">​</a></h3><p>代码里两种模式都在，靠宏切换。这样做的价值在调试期：怀疑中断通路有问题时，把宏改成 0 就能立刻区分&quot;是中断没进来&quot;还是&quot;网卡本身没在收&quot;。</p><h2 id="五、-诊断手段" tabindex="-1">五、 诊断手段 <a class="header-anchor" href="#五、-诊断手段" aria-label="Permalink to &quot;五、 诊断手段&quot;">​</a></h2><h3 id="_1-串口日志与计数统计" tabindex="-1">1. 串口日志与计数统计 <a class="header-anchor" href="#_1-串口日志与计数统计" aria-label="Permalink to &quot;1. 串口日志与计数统计&quot;">​</a></h3><p>网络不通时最怕的是&quot;完全没有观测点&quot;。这个工程留了两层：</p><table tabindex="0"><thead><tr><th>手段</th><th>开关/入口</th><th>内容</th></tr></thead><tbody><tr><td>串口日志</td><td>常开</td><td>初始化结果、每帧收发的结论、错误原因</td></tr><tr><td>计数统计</td><td><code>DM9000_NETDBG_EN</code></td><td>EXTI 触发次数、成功取包数、因状态/内存丢弃的包数、发送次数</td></tr><tr><td>周期打印</td><td><code>DM9000_DbgPoll()</code></td><td>每拍由 <code>lwip_comm_poll()</code> 调用，每 2 秒打一行</td></tr></tbody></table><p>计数统计是排查&quot;丢包&quot;的主力，三种典型读数：</p><p>（1）<code>exti</code> 远大于 <code>rx_ok</code>：标志置了却没被主循环及时取走（主循环被什么堵住了）。</p><p>（2）<code>rx_drop</code> 持续增长：多半是 <code>pbuf_alloc</code> 失败，即 <code>PBUF_POOL_SIZE = 8</code> 被用完。</p><p>（3）<code>nsr</code> 低位异常：PHY 链路状态没协商好，先查网线再看驱动。</p><h3 id="_2-排错速查" tabindex="-1">2. 排错速查 <a class="header-anchor" href="#_2-排错速查" aria-label="Permalink to &quot;2. 排错速查&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th></tr></thead><tbody><tr><td><code>DM9000: ID = 0x00000000</code> 或 <code>0xFFFFFFFF</code></td><td>FSMC 未初始化、片选错、总线宽度/时序不对</td></tr><tr><td>串口完全没有 <code>DM9000:</code> 打印</td><td><code>LWIP_APP_EN</code> 被置 0，或 <code>lwip_comm_init()</code> 没被调用</td></tr><tr><td>能 ping 通但 TCP 连不上</td><td>端口被别的会话占着（单连接策略）；或 <code>IAP_TCP_EN</code> 为 0</td></tr><tr><td>第一次收包后就再也没包</td><td>中断标志没清（第四节第 2 小节）</td></tr><tr><td>升级到一半板子卡死</td><td>收帧超时（默认 3000 ms）后状态机重对齐，检查 PC 侧是否被防火墙/杀软拖慢</td></tr><tr><td>跳转 APP 后起步就卡死</td><td>跳转前网络通道没关干净，见 <a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5261051823e07.html">LV025-基于TFTP的网络升级实验</a> 第六节</td></tr></tbody></table><h2 id="六、-小结与参考资料" tabindex="-1">六、 小结与参考资料 <a class="header-anchor" href="#六、-小结与参考资料" aria-label="Permalink to &quot;六、 小结与参考资料&quot;">​</a></h2><h3 id="_1-本篇小结" tabindex="-1">1. 本篇小结 <a class="header-anchor" href="#_1-本篇小结" aria-label="Permalink to &quot;1. 本篇小结&quot;">​</a></h3><ul><li>实验的三个层次：ping（验证 IP/ICMP/ARP）、TCP 连通性（<code>nc</code> 握手）、真实升级（发 <code>IAPBIN01</code> 帧）。</li><li>上电日志的五行分别对应链路层、网络层、收包路径、协议栈就绪与 TCP 通道，任何一行不对都能立刻缩小排查范围。</li><li>TCP 通道是<strong>单连接</strong>的，建连时独占帧状态机、断连时归还串口；<code>go</code> / <code>reboot</code> 走 TCP 同样有效。</li><li>收包有中断与轮询两种模式，靠宏切换；中断模式必须写 1 清 <code>ISR</code>，否则只有第一次能收到包。</li><li>观测点分两层：常开的串口日志 + 可开关的驱动计数；计数用来区分&quot;中断没来&quot;&quot;主循环没取&quot;&quot;内存不够&quot;。</li><li>开发顺序是&quot;先硬件与协议栈、再通道与协议&quot;，这个顺序本身就是一套排错方法论。</li></ul><h3 id="_2-参考资料" tabindex="-1">2. 参考资料 <a class="header-anchor" href="#_2-参考资料" aria-label="Permalink to &quot;2. 参考资料&quot;">​</a></h3><ul><li>手册：<a href="https://gitee.com/docs-site/scm-reference-guide/raw/main/30-STM32%E8%B5%84%E6%96%99/10-lwIP/STM32F1%20LWIP%E5%BC%80%E5%8F%91%E6%89%8B%E5%86%8C%28DM9000%E7%89%88%29_V1.1.pdf" target="_blank" rel="noreferrer"><code>30-STM32资料/10-lwIP/STM32F1 LWIP开发手册(DM9000版)_V1.1.pdf</code></a> 第 1.6 节「下载验证」、第三章 UDP、第五章 TCP 服务器</li><li>源码：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/port/lwip_comm.c" target="_blank" rel="noreferrer"><code>lwip_comm.c</code></a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/port/iap_tcp.c" target="_blank" rel="noreferrer"><code>iap_tcp.c</code></a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Drivers/BSP/Ethernet/dm9000.c" target="_blank" rel="noreferrer"><code>dm9000.c</code></a></li><li>上位机：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/tools/send_iap_tcp.py" target="_blank" rel="noreferrer"><code>tools/send_iap_tcp.py</code></a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/tools/pack_iap.py" target="_blank" rel="noreferrer"><code>tools/pack_iap.py</code></a></li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,69)])])}const u=t(n,[["render",l]]);export{k as __pageData,u as default};
